import { Badge } from "@/components/ui/badge"
import { LinkButton } from "@/components/ui/button"
import { SemanticContent } from "@/components/ui/semantic-content"
import { StatusMark } from "@/components/ui/status-mark"

type Action = { label: string; href: string }
type Stat = { label: string; value: string; tone?: "neutral" | "success" | "warning" | "danger" | "info" }

const headingSize = {
  display: "text-4xl md:text-5xl",
  standard: "text-3xl md:text-4xl",
  compact: "text-xl md:text-2xl",
} as const

/**
 * Section header: optional eyebrow badge, heading, description, up to two
 * actions and an optional stats row. align.start | align.center and
 * density.display | standard | compact are the closed members.
 */
export default function SectionHeader({
  align = "start",
  density = "standard",
  eyebrow,
  heading = "Built for every team",
  description = "Everything you need to plan, ship and measure in one place.",
  actions = [],
  stats = [],
}: {
  align?: "start" | "center"
  density?: "display" | "standard" | "compact"
  eyebrow?: string
  heading?: string
  description?: string
  actions?: Action[]
  stats?: Stat[]
}) {
  const centered = align === "center"
  return (
    <header
      data-slot="section-header"
      data-align={align}
      data-density={density}
      className={centered ? "mx-auto flex max-w-2xl flex-col items-center gap-4 text-center" : "flex max-w-3xl flex-col items-start gap-4"}
    >
      {eyebrow && <Badge variant="secondary">{eyebrow}</Badge>}
      <h2 className={`font-heading font-semibold tracking-tight text-balance text-foreground ${headingSize[density]}`}>{heading}</h2>
      {description && (
        <SemanticContent as="p" className="max-w-2xl text-muted-foreground">
          {description}
        </SemanticContent>
      )}
      {actions.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {actions.slice(0, 2).map((a, i) => (
            <LinkButton key={a.label} href={a.href} variant={i === 0 ? "default" : "outline"}>
              {a.label}
            </LinkButton>
          ))}
        </div>
      )}
      {stats.length > 0 && (
        <SemanticContent as="dl" className={centered ? "flex flex-wrap justify-center gap-6" : "flex flex-wrap gap-6"}>
          {stats.map((s) => (
            <div key={s.label} className="flex flex-col gap-1">
              <SemanticContent as="dt">{s.label}</SemanticContent>
              <SemanticContent as="dd">
                <StatusMark tone={s.tone ?? "neutral"}>{s.value}</StatusMark>
              </SemanticContent>
            </div>
          ))}
        </SemanticContent>
      )}
    </header>
  )
}
